def reduce_l(map_f: Callable[[A, A], A], iterable: Iterable[A], initial: B):
    return foldl_l(map_f, initial, iterable)


def accumulate_l(map_f: Callable[[A, A], A], iterable: Iterable[A]):
    """
    >>> accumulate_l(lambda a, b: a + b, [1, 2, 3, 4])
    [1, 3, 6, 10]

    >>> accumulate_l(lambda a, b: a + b, [[1], 2, [3]])
    [[1], [1, 2], [1, 2, 3]]
    """

    return [reduce_l(map_f, iterable, i) for i in iterable]


